  lines.push("");

  lines.push(
    "Date,In,Out,Paid Meal Break,Unpaid Meal Break,Rate,Regular (h),OT (h),Overtime Rate OT,OT2 (h),Overtime Rate OT2,Hours (h),Regular Amount,OT Amount,OT2 Amount,Total Amount"
  );



