        var name = p.name || poolTypeNames[p.type] || p.type;
        if (p.type === 'custom') return name + ' $' + (p.amount != null ? p.amount : 0) + ' × ' + (p.pct != null ? p.pct : 100) + '%';
        return p.pct != null ? name + ' × ' + p.pct + '%' : name;
