    getRulePoolKindTagClass: getRulePoolKindTagClass,
    normalizeWorkHoursConfig: normalizeWorkHoursConfig,
    formatDistributionName: formatDistributionName,
    poolTypeNames: poolTypeNames,
    distNames: distNames
